:root {
  --ink: #000000;
  --paper: #FFFFFF;
  --accent: #B54131;
  --border: #D6D6D6;
  --support: #555555;
  --radius: 5px;
  --space: 16px;
}

body { margin: 0; padding: 24px; background: var(--paper); color: var(--ink); font-family: "Noto Sans", sans-serif; }
.skip { display: inline-block; margin-bottom: 16px; color: var(--accent); }
header { max-width: 880px; margin-bottom: 24px; }
main { max-width: 880px; }
.status-grid { display: grid; gap: 16px; grid-template-columns: repeat(3, minmax(0, 1fr)); }
.panel { padding: var(--space); border: 1px solid var(--border); border-radius: var(--radius); }
table { width: 100%; border-collapse: collapse; margin-top: var(--space); }
th, td { text-align: left; padding: 8px; border-bottom: 1px solid var(--border); }
.primary { color: var(--accent); }
@media (max-width: 700px) {
  .status-grid { grid-template-columns: 1fr; }
}

